#include <stdio.h>
int main(void) {
    int x[4] = {3, 1, 4, 2};
    int s[4];
    int i;
    for (i = 0; i < 4; i++) s[i] = x[i];
    printf("After load:");
    for (i = 0; i < 4; i++) printf(" %d", s[i]);
    printf("\n");
    s[0] = x[0] + x[1];
    s[1] = x[2] + x[3];
    printf("After step 1:");
    for (i = 0; i < 4; i++) printf(" %d", s[i]);
    printf("\n");
    s[0] = s[0] + s[1];
    printf("Final sum: %d\n", s[0]);
    return 0;
}
